<?php
namespace App\Models;use Illuminate\Database\Eloquent\Factories\HasFactory;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\SoftDeletes;
class Survey extends Model{use HasFactory,SoftDeletes;protected $fillable=['floor_id','floor_plan_id','survey_area_id','created_by','name','purpose','target_ssid','status','minimum_points','notes','started_at','completed_at','lock_version'];protected function casts():array{return ['started_at'=>'datetime','completed_at'=>'datetime'];}public function floor(){return $this->belongsTo(Floor::class);}public function floorPlan(){return $this->belongsTo(FloorPlan::class);}public function surveyArea(){return $this->belongsTo(SurveyArea::class);}public function creator(){return $this->belongsTo(User::class,'created_by');}public function runs(){return $this->hasMany(SurveyRun::class);}public function points(){return $this->hasMany(MeasurementPoint::class);}public function canGenerateHeatmap():bool{return $this->points()->where('validation_status','valid')->count()>=$this->minimum_points;}public function imports(){return $this->hasMany(MeasurementImport::class);}}
